(110,1,'2026-05-26 08:48:31','2026-05-26 06:48:31','<!-- wp:shortcode -->\n[xyz-ips snippet=\"contact\"]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<form method=\"POST\" action=\"../contact\">\n    <label for=\"nom\">Nom  </label>\n    <input id=\"nom\" type=\"string\" name=\"nom\">\n    <br>\n    <label for=\"email\">Email</label>\n    <input id=\"email\" type=\"email\" name=\"email\">\n    <br>\n    <label for=\"objet\">Objet</label>\n    <input id=\"objet\" type=\"string\" name=\"objet\">\n    <br>\n    <input id=\"submit\" type=\"submit\" name=\"ajouter\" class=\"submit\" value=\"Envoyer\">\n</form>\n<!-- /wp:html -->','contact','','inherit','closed','closed','','63-revision-v1','','','2026-05-26 08:48:31','2026-05-26 06:48:31','',63,'http://localhost/?p=110',0,'revision','',0),
